components.css:
.ds-page-hero { display: flex; flex-direction: column; gap: 1rem; }
.ds-page-hero-row { display: flex; flex-direction: column; gap: 0.75rem; justify-content: space-between; }
@media (min-width: 640px) { .ds-page-hero-row { flex-direction: row; align-items: flex-start; } }
.ds-page-hero-id { display: flex; min-width: 0; align-items: center; gap: 0.625rem; }
.ds-page-hero-icon { display: flex; width: 1.25rem; height: 1.25rem; flex-shrink: 0; align-items: center; justify-content: center; color: var(--primary); }
.ds-page-hero-text { min-width: 0; }
.ds-page-hero-title { margin: 0; font-family: var(--font-sans); font-size: 1.125rem; font-weight: 600; line-height: 1.2; letter-spacing: -0.025em; }
.ds-page-hero-desc { margin: 0.125rem 0 0 0; font-size: 0.75rem; color: var(--muted-foreground); }
.ds-page-hero-meta { display: flex; width: 100%; flex-wrap: wrap; align-items: center; gap: 0.5rem; }
@media (min-width: 640px) { .ds-page-hero-meta { width: auto; justify-content: flex-end; } }

.ds-btn-primary { display: inline-flex; align-items: center; justify-content: center; height: 2.25rem; padding: 0 1rem; border: 0; border-radius: 0.25rem; background-color: var(--primary); color: var(--primary-foreground); font-family: var(--font-sans); font-size: 0.875rem; font-weight: 500; cursor: pointer; transition: opacity 0.15s ease-out; }
.ds-btn-primary:hover { opacity: 0.9; }
.ds-btn-primary:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

.ds-list { overflow: hidden; border-radius: 0.75rem; border: 1px solid var(--border); background-color: oklch(0.9665 0.0067 97.3521 / 0.4); }
.ds-row { display: flex; align-items: center; gap: 0.75rem; padding: 1rem 1.25rem; border-top: 1px solid var(--border); text-decoration: none; color: var(--foreground); transition: background-color 0.15s ease-out; animation: ds-dash-enter 0.3s ease-out both; animation-delay: var(--dash-delay, 0ms); }
.ds-row:first-child { border-top: 0; }
.ds-row:hover { background-color: oklch(0.9341 0.0153 90.239 / 0.4); }
.ds-row:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
.ds-row-disabled { opacity: 0.6; }
.ds-row-dot { display: inline-block; width: 0.375rem; height: 0.375rem; border-radius: 9999px; background-color: var(--primary); flex-shrink: 0; }
.ds-row-dot-inactive { background-color: var(--border); }
.ds-row-name { font-family: var(--font-sans); font-weight: 500; font-size: 0.875rem; letter-spacing: -0.01em; flex: 1; min-width: 0; }
.ds-row:hover .ds-row-name { color: var(--primary); }
.ds-row-meta { display: grid; grid-template-columns: auto auto; gap: 0.5rem 1.5rem; align-items: center; }
.ds-row-meta-item { display: flex; flex-direction: column; gap: 0.125rem; }
.ds-row-meta-label { font-family: var(--font-sans); font-size: 0.625rem; font-weight: 500; color: oklch(0.5341 0.0078 97.4503 / 0.8); text-transform: uppercase; letter-spacing: 0.12em; }
.ds-row-meta-value { font-family: var(--font-mono); font-size: 0.75rem; font-variant-numeric: tabular-nums; color: var(--muted-foreground); }
@keyframes ds-dash-enter { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

.ds-snav { position: relative; display: flex; flex-direction: column; overflow: hidden; border-radius: 0.75rem; border: 1px solid var(--border); background-color: oklch(0.9665 0.0067 97.3521 / 0.4); padding: 1.25rem; color: var(--foreground); text-decoration: none; transition: background-color 0.15s ease-out; animation: ds-dash-enter 0.3s ease-out both; animation-delay: var(--dash-delay, 0ms); }
.ds-snav:hover { background-color: oklch(0.9341 0.0153 90.239 / 0.4); }
.ds-snav:hover .ds-snav-cta { color: var(--foreground); }
.ds-snav:hover .ds-snav-cta svg { transform: translateX(2px); }
.ds-snav:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
.ds-snav-icon { color: var(--primary); width: 1.25rem; height: 1.25rem; }
.ds-snav-body { margin-top: 1rem; min-height: 0; flex: 1; }
.ds-snav-title { margin: 0; font-family: var(--font-sans); font-size: 1rem; font-weight: 500; letter-spacing: -0.01em; }
.ds-snav-desc { margin: 0.125rem 0 0 0; font-size: 0.75rem; color: var(--muted-foreground); line-height: 1.5; }
.ds-snav-cta { margin-top: 1.5rem; display: flex; align-items: center; gap: 0.25rem; font-family: var(--font-sans); font-size: 0.75rem; color: var(--muted-foreground); transition: color 0.15s ease-out; }
.ds-snav-cta svg { transition: transform 0.15s ease-out; }

.ds-state { position: relative; display: flex; flex-direction: column; align-items: center; gap: 0.75rem; overflow: hidden; border-radius: 0.75rem; border: 1px dashed var(--border); background-color: oklch(0.9665 0.0067 97.3521 / 0.4); padding: 4rem 1.5rem; text-align: center; }
.ds-state-icon { display: flex; width: 2.5rem; height: 2.5rem; align-items: center; justify-content: center; color: var(--muted-foreground); animation: ds-dash-pop 0.25s ease-out both; animation-delay: var(--dash-delay, 0ms); }
.ds-state-title { margin: 0; font-family: var(--font-sans); font-size: 1rem; font-weight: 500; letter-spacing: -0.01em; color: var(--foreground); }
.ds-state-desc { margin: 0.25rem auto 0 auto; max-width: 24rem; font-family: var(--font-sans); font-size: 0.875rem; line-height: 1.5; color: var(--muted-foreground); }
.ds-state-action { position: relative; margin-top: 0.25rem; }

.ds-btn-outline { display: inline-flex; align-items: center; justify-content: center; height: 2.25rem; padding: 0 1rem; border: 1px solid var(--border); border-radius: 0.25rem; background-color: transparent; color: var(--foreground); font-family: var(--font-sans); font-size: 0.875rem; font-weight: 500; cursor: pointer; transition: background-color 0.15s ease-out; }
.ds-btn-outline:hover { background-color: oklch(0.9341 0.0153 90.239 / 0.4); }
.ds-btn-outline:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

@keyframes ds-dash-pop { from { opacity: 0; transform: scale(0.85); } to { opacity: 1; transform: scale(1); } }
@keyframes ds-dash-enter { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

.ds-dialog-backdrop { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; background-color: oklch(0 0 0 / 0.5); padding: 1rem; }
.ds-dialog { display: flex; flex-direction: column; width: 100%; max-width: 32rem; max-height: calc(100vh - 2rem); background-color: var(--background); border: 1px solid var(--border); border-radius: 0.5rem; overflow: hidden; }
.ds-dialog-header { display: flex; flex-direction: column; gap: 0.375rem; padding: 1.25rem 1.5rem; border-bottom: 1px solid var(--border); text-align: left; }
.ds-dialog-title { margin: 0; font-family: var(--font-sans); font-size: 1.125rem; font-weight: 600; line-height: 1.2; letter-spacing: -0.025em; color: var(--foreground); }
.ds-dialog-desc { margin: 0; font-family: var(--font-sans); font-size: 0.75rem; line-height: 1.5; color: var(--muted-foreground); }
.ds-dialog-form { display: flex; flex-direction: column; overflow-y: auto; }
.ds-dialog-body { display: flex; flex-direction: column; gap: 1rem; padding: 1.25rem 1.5rem; }
.ds-dialog-footer { display: flex; justify-content: flex-end; gap: 0.5rem; padding: 1rem 1.5rem; border-top: 1px solid var(--border); }

.ds-field { display: flex; flex-direction: column; gap: 0.5rem; min-width: 0; }
.ds-field-label { display: block; font-family: var(--font-sans); font-size: 0.625rem; font-weight: 500; color: oklch(0.5341 0.0078 97.4503 / 0.8); text-transform: uppercase; letter-spacing: 0.12em; }

.ds-input { display: block; width: 100%; height: 2.25rem; padding: 0 0.75rem; border: 1px solid var(--input); border-radius: 0.375rem; background-color: transparent; color: var(--foreground); font-family: var(--font-sans); font-size: 0.875rem; }
.ds-input:focus { outline: 2px solid var(--ring); outline-offset: 2px; border-color: var(--ring); }
.ds-input-mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

.ds-label-stack { display: flex; flex-direction: column; gap: 0.375rem; min-width: 0; }
.ds-label { margin: 0; font-family: var(--font-sans); font-size: 0.625rem; font-weight: 500; color: oklch(0.5341 0.0078 97.4503 / 0.8); text-transform: uppercase; letter-spacing: 0.12em; }
.ds-label-value { font-family: var(--font-mono); font-size: 0.75rem; font-variant-numeric: tabular-nums; color: var(--foreground); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.ds-search { position: relative; width: 100%; }
@media (min-width: 640px) { .ds-search { max-width: 20rem; } }
.ds-search-icon { position: absolute; top: 50%; left: 0.625rem; width: 0.875rem; height: 0.875rem; transform: translateY(-50%); color: var(--muted-foreground); pointer-events: none; }
.ds-search-input { display: block; width: 100%; height: 2rem; padding: 0 0.75rem 0 2rem; border: 1px solid var(--input); border-radius: 0.375rem; background-color: transparent; color: var(--foreground); font-family: var(--font-sans); font-size: 0.875rem; }
.ds-search-input::placeholder { color: var(--muted-foreground); }
.ds-search-input:focus { outline: 2px solid var(--ring); outline-offset: 2px; border-color: var(--ring); }
